package cn.yulin.english;
import android.content.Context;import org.json.*;import java.io.*;import java.security.*;import java.util.*;
/** Materialize only the requested packaged original; never require a network connection. */
public final class BuiltinArchive {
 private final Context context;private final Map<String,JSONObject> paths=new HashMap<>();
 public BuiltinArchive(Context c)throws Exception{context=c;try(InputStream in=c.getAssets().open("builtin-manifest.json");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);JSONArray a=new JSONObject(out.toString("UTF-8")).getJSONArray("files");for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);paths.put(x.getString("sourcePath"),x);}}}
 public boolean contains(String path){return paths.containsKey(path);}
 public synchronized File open(String path)throws Exception{JSONObject x=paths.get(path);if(x==null)throw new IOException("未找到内置资料");String sha=x.getString("sha256"),ext=x.getString("extension");if(!sha.matches("[a-f0-9]{64}")||!ext.matches("doc|docx|pdf|mp3|wav|amr|jpg|jpeg|png|rar|zip"))throw new IOException("资料索引无效");File dir=new File(context.getFilesDir(),"cloud");dir.mkdirs();File file=new File(dir,sha+"."+ext);if(file.isFile()&&file.length()==x.getLong("bytes"))return file;if(dir.getUsableSpace()<x.getLong("bytes")+10485760)throw new IOException("请先释放设备存储空间");File tmp=new File(dir,file.getName()+".builtin.tmp");MessageDigest digest=MessageDigest.getInstance("SHA-256");try{try(InputStream in=context.getAssets().open("archive/"+file.getName());FileOutputStream out=new FileOutputStream(tmp)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){out.write(b,0,n);digest.update(b,0,n);}out.getFD().sync();}StringBuilder hash=new StringBuilder();for(byte b:digest.digest())hash.append(String.format(Locale.ROOT,"%02x",b&255));if(tmp.length()!=x.getLong("bytes")||!sha.equals(hash.toString()))throw new IOException("内置资料校验失败");if(!tmp.renameTo(file))throw new IOException("资料无法保存");return file;}finally{tmp.delete();}}
}
